    <script>
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) return null;
            return chatMessages[0].message;
        }

        function extractText(str, regex, defaultVal) {
            var match = str.match(regex);
            if (match && match[1]) {
                return match[1].replace(/<[^>]+>/g, '').trim();
            }
            return defaultVal || '';
        }

        function parseData(messageText) {
            var data = {
                sysTime: '', location: '', statusType: 'notes', statusName: 'notes',
                statusData: [], anchors: [], targets: [], actions: []
            };

            var blockMatch = messageText.match(/<Status_block>([\s\S]*?)<\/Status_block>/);
            if (!blockMatch) return data;
            var text = blockMatch[1];

            /* 基础信息 */
            data.sysTime = extractText(text, /日期：(.*?)\s*\|/);
            data.location = extractText(text, /位置：(.*?)[』】]/);

            /* 状态解析 */
            var statusSection = '';
            var statusMatch = text.match(/<details><summary><b>👨 『notes \| 本体状态』<\/b><\/summary>([\s\S]*?)<\/details>/);

            if (statusMatch) {
                statusSection = statusMatch[1];
                data.statusType = 'notes';
                data.statusName = 'notes';
                var lines = statusSection.split('\n');
                lines.forEach(function(line) {
                    if (line.trim().match(/^[-]*\s*[🧑‍💼👔💭🍆📅]/)) {
                        var parts = line.split('：');
                        if (parts.length >= 2) {
                            var iconAndLabel = parts[0].replace(/[-]/g, '').trim();
                            var val = parts.slice(1).join('：').trim();
                            data.statusData.push({ label: iconAndLabel, value: val });
                        }
                    }
                });
            } else {
                var femaleMatch = text.match(/『(.*?)的状态』([\s\S]*?)<\/details>/);
                if (femaleMatch) {
                    data.statusType = 'female';
                    data.statusName = femaleMatch[1].trim();
                    statusSection = femaleMatch[2];
                    var fLines = statusSection.split('\n');
                    fLines.forEach(function(line) {
                        if (line.trim().match(/^[-]*\s*[🧑‍💼👗💭🌸🍒🍑📅]/)) {
                            var parts = line.split('：');
                            if (parts.length >= 2) {
                                var iconAndLabel = parts[0].replace(/[-]/g, '').trim();
                                var val = parts.slice(1).join('：').trim();
                                data.statusData.push({ label: iconAndLabel, value: val });
                            }
                        }
                    });
                }
            }

            /* ===== 新增：解析意识锚点 ===== */
            var anchorMatch = text.match(/『意识锚点 \| 可选马甲』.*?<\/summary>([\s\S]*?)<\/details>/);
            if (anchorMatch) {
                var anchorLines = anchorMatch[1].split('\n');
                anchorLines.forEach(function(line) {
                    /* 清除HTML标签，去除首尾空格 */
                    var cleanLine = line.replace(/<[^>]+>/g, '').trim();
                    /* 如果是短横线开头，并且不是那句空资料库的提示语，就当作锚点收录 */
                    if (cleanLine.startsWith('-') && cleanLine.length > 1) {
                        var anchorText = cleanLine.substring(1).trim();
                        if (anchorText.indexOf('资料库为空') === -1) {
                            data.anchors.push(anchorText);
                        }
                    }
                });
            }

            /* 目标推荐解析 */
            var targetRegex = /【推荐目标[一二三]】.*?<\/summary>\s*([\s\S]*?)<\/details>/g;
            var tMatch;
            while ((tMatch = targetRegex.exec(text)) !== null) {
                var tContent = tMatch[1];
                var name = extractText(tContent, /\*\*姓名：\*\*(.*?)\n/);
                var bg = extractText(tContent, /\*\*家室：\*\*(.*?)\n/);
                var looks = extractText(tContent, /\*\*样貌三围：\*\*(.*?)\n/);
                var ai = extractText(tContent, /\*\*AI点评：\*\*(.*?)$/m);
                if (name) data.targets.push({ name: name, bg: bg, looks: looks, ai: ai });
            }

            /* 剧情选项解析 */
            var actionRegex = /\d\.\s*\*\*\[(.*?)\]\*\*\s*(.*)/g;
            var aMatch;
            while ((aMatch = actionRegex.exec(text)) !== null) {
                if (aMatch[1] && aMatch[2]) {
                    data.actions.push({ type: aMatch[1].trim(), text: aMatch[2].trim() });
                }
            }
            return data;
        }

        /* ========== 交互事件 ========== */
        window.toggleAnchor = function() {
            document.getElementById('anchor-panel').classList.toggle('active');
        };

        window.toggleTarget = function(el) {
            var cards = document.querySelectorAll('.target-card');
            cards.forEach(function(c) { if (c !== el) c.classList.remove('active'); });
            el.classList.toggle('active');
        };

        window.sendAction = function(type, text) {
            if (typeof triggerSlash === 'function') {
                triggerSlash('/send 我选择[' + type + ']：' + text + '|/trigger');
            }
        };

        window.openCamera = function() {
            document.getElementById('cam-overlay').classList.add('active');
        };

        window.closeCamera = function(e) {
            if(e) e.stopPropagation();
            document.getElementById('cam-overlay').classList.remove('active');
        };

        window.shootCamera = function() {
            closeCamera();
            if (typeof triggerSlash === 'function') {
                triggerSlash('/send 我激活了【近距离附身】模式，将手机摄像头对准了目标，按下了锁定快门。|/trigger');
            }
        };

        window.activateSoul = function() {
            var container = document.getElementById('main-container');
            container.classList.add('soul-mode');
            setTimeout(function() {
                if (typeof triggerSlash === 'function') {
                    triggerSlash('/send 我激活了【自由附身】模式。肉体进入托管状态，主意识化作无形的灵魂形态剥离而出，准备寻找目标冲入其体内。|/trigger');
                }
                container.classList.remove('soul-mode');
            }, 1500);
        };

        function renderPage(data) {
            var html = '<div class="sys-container" id="main-container">';

            /* 摄像头遮罩层 */
            html += '<div class="camera-overlay" id="cam-overlay">';
            html += '<div class="close-cam" onclick="closeCamera(event)">×</div>';
            html += '<div class="crosshair" onclick="shootCamera()">';
            html += '<div class="crosshair-corner cc-tl"></div><div class="crosshair-corner cc-tr"></div>';
            html += '<div class="crosshair-corner cc-bl"></div><div class="crosshair-corner cc-br"></div>';
            html += '</div>';
            html += '<div class="cam-text">请将镜头对准目标并点击快门</div>';
            html += '</div>';

            html += '<div class="sys-header">';
            html += '<span>Possession App Protocol</span>';
            html += '<span>' + (data.sysTime || 'Just now') + '</span>';
            html += '</div>';

            html += '<div class="sys-content">';

            if (data.location) {
                html += '<div class="location-badge">📍 ' + data.location + '</div>';
            }

            if (data.statusData.length > 0) {
                var titleText = data.statusType === 'notes' ? '状态监控 [本体]' : '状态监控 [马甲: ' + data.statusName + ']';
                html += '<div class="section-title">' + titleText + '</div>';
                html += '<div class="status-list">';
                data.statusData.forEach(function(item) {
                    html += '<div class="data-row">';
                    html += '<div class="data-label">' + item.label + '</div>';
                    html += '<div class="data-value">' + item.value + '</div>';
                    html += '</div>';
                });
                html += '</div>';
            }

            /* ===== 新增：意识锚点折叠面板 ===== */
            html += '<div class="section-title">已建立锚点 (马甲库)</div>';
            html += '<div class="anchor-panel" id="anchor-panel">';
            html += '<div class="anchor-header" onclick="toggleAnchor()">当前可用锚点数量：' + data.anchors.length + '</div>';
            html += '<div class="anchor-body">';
            if (data.anchors.length > 0) {
                data.anchors.forEach(function(anchor) {
                    html += '<div class="anchor-item">' + anchor + '</div>';
                });
            } else {
                html += '<div class="anchor-empty">资料库为空，请先执行首次附身以建立锚点。</div>';
            }
            html += '</div></div>';

            /* 附身模式控制台 */
            html += '<div class="section-title">战术指令覆盖</div>';
            html += '<div class="protocol-panel">';

            html += '<div class="protocol-btn cam-mode" onclick="openCamera()">';
            html += '<div class="protocol-title">近距离附身</div>';
            html += '<div class="protocol-desc">摄像头锁定 | 深度3</div>';
            html += '</div>';

            html += '<div class="protocol-btn soul-mode" onclick="activateSoul()">';
            html += '<div class="protocol-title">自由附身</div>';
            html += '<div class="protocol-desc">灵魂离体 | 无视碰撞</div>';
            html += '</div>';

            html += '</div>';

            if (data.targets.length > 0) {
                html += '<div class="section-title">高价值目标推荐 (智能策应)</div>';
                data.targets.forEach(function(target, index) {
                    html += '<div class="target-card" onclick="toggleTarget(this)">';
                    html += '<div class="target-header">目标 ' + (index + 1) + '：' + target.name + '</div>';
                    html += '<div class="target-body">';
                    html += '<div class="data-row"><div class="data-label">背景信息</div><div class="data-value">' + target.bg + '</div></div>';
                    html += '<div class="data-row"><div class="data-label">身体参数</div><div class="data-value">' + target.looks + '</div></div>';
                    html += '<div class="data-row ai-eval"><div class="data-label">AI 评估</div><div class="data-value">' + target.ai + '</div></div>';
                    html += '</div></div>';
                });
            }

            if (data.actions.length > 0) {
                html += '<div class="section-title">下一步行动</div>';
                html += '<div class="action-list">';
                data.actions.forEach(function(action) {
                    var safeText = action.text.replace(/'/g, "\\'");
                    html += '<div class="action-btn" onclick="sendAction(\'' + action.type + '\', \'' + safeText + '\')">';
                    html += '<span class="action-type">' + action.type + '</span>';
                    html += '<span>' + action.text + '</span>';
                    html += '</div>';
                });
                html += '</div>';
            }

            html += '</div></div>';
            document.getElementById('content').innerHTML = html;
        }

        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) return;
                var data = parseData(messageText);
                renderPage(data);
            } catch (error) {
                console.error("解析错误:", error);
            }
        }

        $(function() { init(); });
    </script>
